3781.sent:
// Microsoft Sentinel — auto-derived from the Defender XDR hunt.
// Requires the Microsoft 365 Defender data connector (streams the
// advanced-hunting tables into Sentinel; Timestamp → TimeGenerated).
let lookback = 90d;
let badDomain = "npmjs.help";
let urls = EmailUrlInfo
    | where TimeGenerated > ago(lookback)
    | where UrlDomain endswith badDomain or Url has badDomain
    | project TimeGenerated, NetworkMessageId, Url, UrlDomain;
let senders = EmailEvents
    | where TimeGenerated > ago(lookback)
    | where SenderFromDomain endswith badDomain
         or SenderMailFromDomain endswith badDomain
         or SenderFromAddress has "@npmjs.help"
    | project TimeGenerated, NetworkMessageId, SenderFromAddress, SenderFromDomain, RecipientEmailAddress, Subject, DeliveryAction, DeliveryLocation;
senders
| union (urls | join kind=inner (EmailEvents | where TimeGenerated > ago(lookback)) on NetworkMessageId
         | project TimeGenerated, NetworkMessageId, SenderFromAddress, SenderFromDomain, RecipientEmailAddress, Subject, DeliveryAction, DeliveryLocation, Url, UrlDomain)
| order by TimeGenerated desc

